mapper.select:
SELECT id, tenant_id, event_id, aggregate_type, aggregate_id, aggregate_version,
       application_id, action, actor_id, payload_json, occurred_at
FROM audit_event
WHERE occurred_at < #{cutoff}

    AND tenant_id = #{tenantId}

  AND NOT EXISTS (
      SELECT 1 FROM expense_budget_review r
      WHERE r.tenant_id = audit_event.tenant_id
        AND (r.decision_audit_id = audit_event.event_id OR r.automatic_audit_id = audit_event.event_id)
  )
ORDER BY occurred_at ASC, id ASC
LIMIT #{limit}

SELECT id, tenant_id, cutoff_at, archived_count, triggered_by, executed_at
FROM audit_retention_run
WHERE tenant_id = #{tenantId}
ORDER BY executed_at DESC
LIMIT #{limit}

SELECT COUNT(*) AS total_count
FROM audit_event_archive
WHERE tenant_id = #{tenantId}
